"""Infix to Postfix — shunting-yard with an operator stack.

Operands go straight to the output. An operator pops every stacked operator of
greater-or-equal precedence first (strictly greater for the right-associative
'^'), which is what encodes the precedence rules.

Time: O(n)   Space: O(n)
"""

PRECEDENCE = {"+": 1, "-": 1, "*": 2, "/": 2, "^": 3}


class Solution:
    def infixToPostfix(self, s: str) -> str:
        out, stack = [], []
        for ch in s:
            if ch.isalnum():
                out.append(ch)
            elif ch == "(":
                stack.append(ch)
            elif ch == ")":
                while stack and stack[-1] != "(":
                    out.append(stack.pop())
                stack.pop()                      # discard '('
            elif ch in PRECEDENCE:
                while (stack and stack[-1] != "("
                       and (PRECEDENCE[stack[-1]] > PRECEDENCE[ch]
                            or (PRECEDENCE[stack[-1]] == PRECEDENCE[ch] and ch != "^"))):
                    out.append(stack.pop())
                stack.append(ch)
        while stack:
            out.append(stack.pop())
        return "".join(out)
